--
-- Table structure for table `penjualans`
--

DROP TABLE IF EXISTS `penjualans`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `penjualans` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nomor_transaksi` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nomor unik transaksi penjualan',
  `work_unit_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `tanggal_transaksi` datetime NOT NULL COMMENT 'Waktu transaksi',
  `subtotal` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT 'Total sebelum diskon',
  `diskon` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT 'Total diskon',
  `total` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT 'Total setelah diskon',
  `bayar` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT 'Jumlah uang dibayar',
  `kembalian` decimal(15,2) NOT NULL DEFAULT '0.00' COMMENT 'Uang kembalian',
  `metode_pembayaran` enum('tunai','transfer','qris','debit','kredit') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'tunai',
  `nama_pelanggan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nama pembeli (opsional)',
  `catatan` text COLLATE utf8mb4_unicode_ci COMMENT 'Catatan transaksi',
  `status` enum('selesai','dibatalkan') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'selesai',
  `is_entry` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Transaksi sudah di-entry',
  `is_verified` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Transaksi sudah diverifikasi officer',
  `is_approved` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Transaksi sudah diapprove sysadmin',
  `is_recorded` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Transaksi sudah masuk buku kas',
  `verified_by` bigint unsigned DEFAULT NULL,
  `verified_at` timestamp NULL DEFAULT NULL COMMENT 'Waktu verifikasi',
  `approved_by` bigint unsigned DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL COMMENT 'Waktu approve',
  `recorded_by` bigint unsigned DEFAULT NULL,
  `recorded_at` timestamp NULL DEFAULT NULL COMMENT 'Waktu rekam ke buku kas',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `penjualans_nomor_transaksi_unique` (`nomor_transaksi`),
  KEY `penjualans_nomor_transaksi_index` (`nomor_transaksi`),
  KEY `penjualans_work_unit_id_index` (`work_unit_id`),
  KEY `penjualans_user_id_index` (`user_id`),
  KEY `penjualans_tanggal_transaksi_index` (`tanggal_transaksi`),
  KEY `penjualans_status_index` (`status`),
  KEY `penjualans_verified_by_foreign` (`verified_by`),
  KEY `penjualans_approved_by_foreign` (`approved_by`),
  KEY `penjualans_recorded_by_foreign` (`recorded_by`),
  KEY `penjualans_is_verified_index` (`is_verified`),
  KEY `penjualans_is_approved_index` (`is_approved`),
  KEY `penjualans_is_recorded_index` (`is_recorded`),
  CONSTRAINT `penjualans_approved_by_foreign` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`),
  CONSTRAINT `penjualans_recorded_by_foreign` FOREIGN KEY (`recorded_by`) REFERENCES `users` (`id`),
  CONSTRAINT `penjualans_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `penjualans_verified_by_foreign` FOREIGN KEY (`verified_by`) REFERENCES `users` (`id`),
  CONSTRAINT `penjualans_work_unit_id_foreign` FOREIGN KEY (`work_unit_id`) REFERENCES `work_units` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

