INSERT INTO `roles` VALUES (1,'head','web','University leadership with executive dashboard access. Can view comprehensive reports, financial statements, and cash flow analytics. Read-only access for strategic oversight and decision-making.','2026-01-22 10:09:00','2026-01-22 10:09:00'),(2,'sysadmin','web','System administrator with full user management capabilities. Responsible for managing user accounts, assigning roles, and maintaining system security. Has comprehensive access to all cash books and system configurations.','2026-01-22 10:09:00','2026-01-22 10:09:00'),(3,'officer','web','Administrative officer responsible for daily operational tasks. Manages content, financial entries, reports, and unit-specific operations. Full access to create, edit, and manage operational data.','2026-01-22 10:09:00','2026-01-22 10:09:00'),(4,'canteen','web','Canteen staff member with access to order management and inventory tracking. Can view incoming orders, manage stock levels, and monitor canteen-specific transactions.','2026-01-22 10:09:00','2026-01-22 10:09:00'),(5,'shop','web','Shop staff member with access to retail operations. Can manage stock opname, view incoming orders, track inventory levels, and handle shop-specific transactions.','2026-01-22 10:09:00','2026-01-22 10:09:00');
/*!40000 ALTER TABLE `roles` ENABLE KEYS */;
